insert into public.exams (
insert into practice_bank values
('Mathematics',1,'What is 25% of 160? / 160 का 25% कितना है?',array['20','30','40','50'],3,'One quarter of 160 is 40. / 160 का एक चौथाई 40 है।'),
('Mathematics',2,'Divide 180 in the ratio 2:3. Find the larger share. / 180 को 2:3 में बाँटें। बड़ा हिस्सा कितना है?',array['72','90','108','120'],3,'180 x 3/5 = 108. / कुल 5 भागों में से बड़ा हिस्सा 3 भाग अर्थात 108 है।'),
('Mathematics',3,'An item costs 400 and sells for 460. Find the profit percentage. / 400 की वस्तु 460 में बिकी। लाभ प्रतिशत ज्ञात करें।',array['10%','12%','15%','20%'],3,'Profit percentage = (460 - 400)/400 x 100 = 15%. / लाभ 60 है; लागत पर लाभ 15% है।'),
('Mathematics',4,'An 800 price is reduced by 10%, then increased by 10%. Find the final price. / 800 के मूल्य में पहले 10% कमी और फिर 10% वृद्धि हुई। अंतिम मूल्य?',array['792','800','808','720'],1,'800 x 0.9 x 1.1 = 792; equal percentage changes do not cancel. / क्रमिक गुणक 0.9 और 1.1 हैं; अंतिम मूल्य 792 है।'),
('Mathematics',5,'A finishes a job in 15 days, B in 10 days. How long together? / A काम 15 दिन में और B 10 दिन में करता है। दोनों साथ कितने दिन लेंगे?',array['5 days / दिन','6 days / दिन','8 days / दिन','12 days / दिन'],2,'Combined rate = 1/15 + 1/10 = 1/6. / संयुक्त दर 1/6 काम प्रतिदिन है, इसलिए 6 दिन लगेंगे।'),
('Mathematics',6,'A 150 m train at 54 km/h crosses a 225 m platform in how many seconds? / 54 किमी/घंटा की गति से 150 मीटर लंबी रेल 225 मीटर के प्लेटफॉर्म को कितने सेकंड में पार करेगी?',array['15','20','25','30'],3,'54 km/h = 15 m/s; time = (150+225)/15 = 25 s. / कुल दूरी 375 मीटर और गति 15 मीटर/सेकंड है; समय 25 सेकंड।'),
('Mathematics',7,'Find compound interest on 8000 at 5% annually for 2 years. / 8000 पर 5% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज ज्ञात करें।',array['800','820','840','880'],2,'8000 x (1.05 squared - 1) = 820. / मिश्रधन 8820 है; मूलधन घटाने पर ब्याज 820 है।'),
('Mathematics',8,'A 30-litre mixture is milk:water = 2:1. How much is removed and replaced by water to make 1:1? / 30 लीटर मिश्रण में दूध:पानी = 2:1 है। कितना मिश्रण निकालकर उतना पानी मिलाएँ कि अनुपात 1:1 हो?',array['5 L / लीटर','7.5 L / लीटर','10 L / लीटर','15 L / लीटर'],2,'Milk must fall from 20 to 15 litres: (2/3)x = 5, so x = 7.5. / निकाले गए मिश्रण में दूध 5 लीटर होना चाहिए; अतः मिश्रण 7.5 लीटर है।'),
('Mathematics',9,'If x + 1/x = 4, find x cubed + 1/x cubed. / यदि x + 1/x = 4, तो x का घन + 1/x का घन कितना है?',array['48','52','56','64'],2,'(x + 1/x) cubed - 3(x + 1/x) = 64 - 12 = 52. / घन के सूत्र से उत्तर 64 - 12 = 52 है।'),
('Mathematics',10,'Two dice are rolled. Given an even sum, what is the probability that the sum is 8? / दो पासे फेंके गए। योग सम होने पर योग 8 होने की प्रायिकता क्या है?',array['5/36','5/18','1/3','1/2'],2,'There are 18 even-sum outcomes and 5 with sum 8. / सम योग वाले 18 क्रमित परिणामों में 5 का योग 8 है; प्रायिकता 5/18 है।'),
('Reasoning',1,'Find the next number: 4, 8, 12, 16, __. / अगली संख्या ज्ञात करें: 4, 8, 12, 16, __।',array['18','20','22','24'],2,'Each step adds 4, so the next number is 20. / हर बार 4 जुड़ता है, अगली संख्या 20 है।'),
('Reasoning',2,'If A=1, B=2, ..., Z=26, what is the sum for CAB? / यदि A=1, B=2, ..., Z=26 हो, तो CAB का योग क्या है?',array['5','6','7','8'],2,'C+A+B = 3+1+2 = 6. / अक्षरों के मान जोड़ें: 3+1+2 = 6।'),
('Reasoning',3,'R faces north, turns right, then left, then left. Which direction now? / R उत्तर की ओर है, दाएँ, फिर बाएँ, फिर बाएँ मुड़ता है। अब किस दिशा में है?',array['North / उत्तर','South / दक्षिण','East / पूर्व','West / पश्चिम'],4,'North to east to north to west. / दिशाओं का क्रम उत्तर, पूर्व, उत्तर, पश्चिम है।'),
('Reasoning',4,'P is 7th from the front and 9th from the back in a queue. How many people? / P कतार में आगे से 7वाँ और पीछे से 9वाँ है। कुल कितने लोग हैं?',array['14','15','16','17'],2,'7+9-1 = 15; count P only once. / P दोनों गिनतियों में है, इसलिए कुल 7+9-1 = 15।'),
('Reasoning',5,'All clerks are employees. No employee is a visitor. Which follows? / सभी लिपिक कर्मचारी हैं। कोई कर्मचारी आगंतुक नहीं है। कौन-सा निष्कर्ष सही है?',array['Some clerks are visitors / कुछ लिपिक आगंतुक हैं','No clerk is a visitor / कोई लिपिक आगंतुक नहीं है','All visitors are clerks / सभी आगंतुक लिपिक हैं','All employees are clerks / सभी कर्मचारी लिपिक हैं'],2,'Clerks are a subset of employees, so none can be visitors. / लिपिक कर्मचारियों का उपसमूह हैं; इसलिए कोई लिपिक आगंतुक नहीं है।'),
('Reasoning',6,'Find the next term: 1, 3, 7, 15, 31, __. / अगला पद ज्ञात करें: 1, 3, 7, 15, 31, __।',array['47','61','62','63'],4,'Double each term and add 1: 31 x 2 + 1 = 63. / हर पद को दुगुना कर 1 जोड़ें; अगला पद 63 है।'),
('Reasoning',7,'Five people face north. B is immediately right of A, C immediately right of B, D is at the left end and E at the right end. Who is second from right? / पाँच लोग उत्तरमुखी हैं। B, A के ठीक दाएँ; C, B के ठीक दाएँ; D बाएँ छोर पर और E दाएँ छोर पर है। दाएँ से दूसरा कौन?',array['A','B','C','D'],3,'The unique order is D A B C E, so C is second from right. / क्रम D A B C E है; दाएँ से दूसरा C है।'),
('Reasoning',8,'Some files are reports. All reports are digital. No digital item is handwritten. What must follow? / कुछ फाइलें रिपोर्ट हैं। सभी रिपोर्ट डिजिटल हैं। कोई डिजिटल वस्तु हस्तलिखित नहीं है। क्या अवश्य सही है?',array['All files are digital / सभी फाइलें डिजिटल हैं','Some files are not handwritten / कुछ फाइलें हस्तलिखित नहीं हैं','No file is handwritten / कोई फाइल हस्तलिखित नहीं है','All digital items are reports / सभी डिजिटल वस्तुएँ रिपोर्ट हैं'],2,'The files that are reports are digital and cannot be handwritten. / जो फाइलें रिपोर्ट हैं वे डिजिटल हैं, इसलिए हस्तलिखित नहीं हैं।'),
('Reasoning',9,'A is twice B''s age. Eight years ago A was three times B''s age. Find their total age now. / A की आयु B की दुगुनी है। 8 वर्ष पहले A की आयु B की तिगुनी थी। वर्तमान आयु का योग?',array['32','40','48','56'],3,'A=2B and A-8=3(B-8) give B=16, A=32; total 48. / समीकरणों से B=16 और A=32 मिलते हैं; योग 48 वर्ष है।'),
('Reasoning',10,'Seven people face north. C is third, G is at the right end, A is immediately left of B, D immediately right of E, and F is right of C but left of E. Who is fourth? / सात लोग उत्तरमुखी हैं। C तीसरा, G दाएँ छोर पर, A ठीक B के बाएँ, D ठीक E के दाएँ और F, C के दाएँ किंतु E के बाएँ है। चौथा कौन?',array['B','D','E','F'],4,'The constraints force A B C F E D G. Fourth is F. / शर्तों से एकमात्र क्रम A B C F E D G मिलता है; चौथा F है।'),
('English',1,'Choose the plural of child. / child का बहुवचन चुनें।',array['childs','children','childes','childrens'],2,'The irregular plural is children. / child का अनियमित बहुवचन children है।'),
('English',2,'Choose the article: He is __ engineer. / सही उपपद चुनें: He is __ engineer.',array['a','an','no article','some'],2,'Engineer begins with a vowel sound, so use an. / engineer स्वर ध्वनि से शुरू होता है, इसलिए an आएगा।'),
('English',3,'Choose the correct verb: Neither of these keys __ working. / सही क्रिया चुनें: Neither of these keys __ working.',array['are','were','is','have'],3,'Neither of takes a singular verb here: is. / यहाँ Neither of के साथ एकवचन क्रिया is आएगी।'),
('English',4,'Choose the correct preposition: She has lived here __ 2019. / सही पूर्वसर्ग चुनें: She has lived here __ 2019.',array['for','since','from','during'],2,'Use since for a starting point with the present perfect. / पूर्ण वर्तमान काल में आरंभ-बिंदु के लिए since प्रयोग होता है।'),
('English',5,'Choose the passive: They have approved the plan. / सही कर्मवाच्य चुनें: They have approved the plan.',array['The plan is approving.','The plan has approved.','The plan has been approved.','The plan was being approved.'],3,'Present perfect passive is has been plus past participle. / पूर्ण वर्तमान कर्मवाच्य में has been के बाद क्रिया का तीसरा रूप आता है।'),
('English',6,'Choose the correct conditional. / सही शर्तवाचक वाक्य चुनें।',array['If I had studied, I would have passed.','If I had study, I would pass.','If I would study, I had passed.','If I studied, I will have pass.'],1,'An unreal past condition uses had studied and would have passed. / अवास्तविक भूतकालीन शर्त में had studied और would have passed आते हैं।'),
('English',7,'Choose the parallel construction. / समानांतर व्याकरणिक संरचना चुनें।',array['She likes reading, to swim and dancing.','She likes to read, swimming and dance.','She likes reading, swimming and dancing.','She likes read, swimming and dancing.'],3,'All three coordinated activities are gerunds. / तीनों गतिविधियों में समान ing रूप है।'),
('English',8,'Choose the correctly inverted sentence. / सही व्युत्क्रम वाक्य चुनें।',array['Hardly he had arrived when it rained.','Hardly had he arrived when it rained.','Hardly had he arrive than it rained.','Hardly he arrived than it rained.'],2,'Initial hardly requires auxiliary inversion and pairs with when. / आरंभ में Hardly आने पर had, कर्ता से पहले आता है और when जुड़ता है।'),
('English',9,'Passage: Applications doubled after fees fell, but a rival office also closed. Which inference is justified? / अनुच्छेद: शुल्क घटने के बाद आवेदन दुगुने हुए, पर एक प्रतिद्वंद्वी कार्यालय भी बंद हुआ। उचित निष्कर्ष?',array['Fees alone caused the increase / केवल शुल्क से वृद्धि हुई','The closure had no effect / बंद होने का कोई प्रभाव नहीं था','The evidence cannot isolate the sole cause / प्रमाण एकमात्र कारण तय नहीं करता','Lower fees always double applications / कम शुल्क हमेशा आवेदन दुगुने करता है'],3,'Two factors changed together, so sole causation is not established. / दो कारक साथ बदले; किसी एक को एकमात्र कारण नहीं मान सकते।'),
('English',10,'Passage: A screening tool detects more fraud but wrongly flags twice as many genuine transactions. What is supported? / अनुच्छेद: जाँच उपकरण अधिक धोखाधड़ी पकड़ता है पर सही लेनदेन पर गलत चेतावनियाँ भी दुगुनी हैं। क्या समर्थित है?',array['It improves every measure / हर मापदंड सुधरा','It has no false positives / कोई गलत चेतावनी नहीं','It trades more detection for more false positives / अधिक पहचान के साथ गलत चेतावनियाँ भी बढ़ीं','All alerts indicate fraud / सभी चेतावनियाँ धोखाधड़ी हैं'],3,'Detection and false-positive performance move in opposite directions. / पहचान बेहतर हुई लेकिन सही लेनदेन को गलत बताने की समस्या भी बढ़ी।');
insert into practice_bank values
('Polity',1,'Which is the supreme law of India? / भारत का सर्वोच्च कानून कौन-सा है?',array['Constitution / संविधान','An ordinance / अध्यादेश','A municipal rule / नगरपालिका नियम','A party manifesto / दल का घोषणापत्र'],1,'All laws derive validity from the Constitution. / सभी कानूनों की वैधता संविधान के अधीन है।'),
('Polity',2,'Which institution enacts Union legislation? / संघ के कानून कौन-सी संस्था बनाती है?',array['Election Commission / निर्वाचन आयोग','Parliament / संसद','Finance Commission / वित्त आयोग','Comptroller and Auditor General / नियंत्रक एवं महालेखा परीक्षक'],2,'Parliament is the Union legislature. / संसद संघ की विधायिका है।'),
('Polity',3,'Which Article guarantees equality before the law? / विधि के समक्ष समानता किस अनुच्छेद में है?',array['14','19','21','32'],1,'Article 14 guarantees equality before law and equal protection of laws. / अनुच्छेद 14 विधि के समक्ष समानता तथा विधियों का समान संरक्षण देता है।'),
('Polity',4,'Which writ requires a detained person to be produced before a court? / किस रिट से निरुद्ध व्यक्ति को न्यायालय में पेश कराया जाता है?',array['Mandamus / परमादेश','Quo warranto / अधिकार-पृच्छा','Habeas corpus / बंदी प्रत्यक्षीकरण','Prohibition / प्रतिषेध'],3,'Habeas corpus tests the legality of detention. / बंदी प्रत्यक्षीकरण से निरोध की वैधता जाँची जाती है।'),
('Polity',5,'Which constitutional amendment and institution are correctly matched? / किस संविधान संशोधन और संस्था का युग्म सही है?',array['73rd Amendment - municipalities / 73वाँ संशोधन - नगरपालिकाएँ','74th Amendment - panchayats / 74वाँ संशोधन - पंचायतें','73rd Amendment - panchayats / 73वाँ संशोधन - पंचायतें','42nd Amendment - GST / 42वाँ संशोधन - जीएसटी'],3,'The 73rd concerns panchayats; the 74th concerns municipalities. / 73वाँ संशोधन पंचायतों और 74वाँ नगरपालिकाओं से संबंधित है।'),
('Polity',6,'Which statement about a Money Bill is correct? / धन विधेयक के बारे में सही कथन कौन-सा है?',array['It starts only in Rajya Sabha / केवल राज्यसभा में शुरू होता है','It can start in either House / किसी भी सदन में शुरू हो सकता है','It starts only in Lok Sabha / केवल लोकसभा में शुरू होता है','It requires a joint sitting / संयुक्त बैठक आवश्यक है'],3,'A Money Bill can be introduced only in Lok Sabha, with the required recommendation. / आवश्यक सिफारिश के साथ धन विधेयक केवल लोकसभा में पेश होता है।'),
('Polity',7,'Which statement about Directive Principles is correct? / राज्य के नीति निदेशक तत्वों के बारे में सही कथन?',array['They are directly enforceable by courts / न्यायालय सीधे लागू कराते हैं','They guide governance but are not directly enforceable / शासन का मार्गदर्शन करते हैं पर सीधे न्यायालय द्वारा प्रवर्तनीय नहीं','They apply only to local bodies / केवल स्थानीय निकायों पर लागू हैं','They replace Fundamental Rights / मौलिक अधिकारों का स्थान लेते हैं'],2,'Article 37 makes them non-justiciable but fundamental in governance. / अनुच्छेद 37 के अनुसार वे न्यायालय द्वारा प्रवर्तनीय नहीं, किंतु शासन में मूलभूत हैं।'),
('Polity',8,'Which emergency provision permits suspension of Article 19 rights automatically only in a war or external-aggression emergency? / युद्ध या बाहरी आक्रमण वाले आपातकाल में अनुच्छेद 19 के अधिकारों का स्वतः निलंबन किस प्रावधान से होता है?',array['Article 352 alone / केवल अनुच्छेद 352','Article 358 / अनुच्छेद 358','Article 360 / अनुच्छेद 360','Article 368 / अनुच्छेद 368'],2,'After the 44th Amendment, Article 358 applies to war or external aggression, not armed rebellion. / 44वें संशोधन के बाद अनुच्छेद 358 युद्ध या बाहरी आक्रमण पर लागू होता है, सशस्त्र विद्रोह पर नहीं।'),
('Polity',9,'A Constitutional Amendment Bill is passed by Lok Sabha but rejected by Rajya Sabha. Which is correct? / संविधान संशोधन विधेयक लोकसभा में पारित, राज्यसभा में अस्वीकृत हुआ। सही कथन?',array['A joint sitting can pass it / संयुक्त बैठक से पारित हो सकता है','Lok Sabha can override it after 14 days / लोकसभा 14 दिन बाद बाधा हटा सकती है','Both Houses must separately pass it; no joint sitting / दोनों सदनों को अलग-अलग पारित करना होगा; संयुक्त बैठक नहीं','The President can enact it alone / राष्ट्रपति अकेले लागू कर सकते हैं'],3,'Article 368 requires separate passage by each House with the prescribed majority. / अनुच्छेद 368 के अनुसार दोनों सदनों में निर्धारित बहुमत से अलग-अलग पारित होना आवश्यक है।'),
('Polity',10,'Parliament amends the Constitution to abolish judicial review entirely. Which doctrine is most directly relevant? / संसद संविधान संशोधन से न्यायिक समीक्षा पूर्णतः समाप्त करती है। कौन-सा सिद्धांत सीधे प्रासंगिक है?',array['Pleasure doctrine / प्रसादपर्यंत सिद्धांत','Basic structure doctrine / मूल संरचना सिद्धांत','Collective responsibility alone / केवल सामूहिक उत्तरदायित्व','Territorial nexus alone / केवल क्षेत्रीय संबंध'],2,'Judicial review is part of the basic structure, which amendment power cannot destroy. / न्यायिक समीक्षा मूल संरचना का अंग है; संशोधन शक्ति इसे नष्ट नहीं कर सकती।'),
('History',1,'Who founded the Mauryan Empire? / मौर्य साम्राज्य का संस्थापक कौन था?',array['Ashoka / अशोक','Chandragupta Maurya / चंद्रगुप्त मौर्य','Harsha / हर्ष','Kanishka / कनिष्क'],2,'Chandragupta Maurya established the Mauryan Empire. / चंद्रगुप्त मौर्य ने मौर्य साम्राज्य की स्थापना की।'),
('History',2,'The Great Bath was found at which Harappan site? / विशाल स्नानागार किस हड़प्पा स्थल पर मिला?',array['Mohenjo-daro / मोहनजोदड़ो','Lothal / लोथल','Kalibangan / कालीबंगा','Dholavira / धोलावीरा'],1,'Mohenjo-daro contains the structure called the Great Bath. / विशाल स्नानागार मोहनजोदड़ो में स्थित है।'),
('History',3,'Who issued most of the famous Mauryan rock edicts? / प्रसिद्ध मौर्य शिलालेखों का अधिकांश किसने जारी किया?',array['Bindusara / बिंदुसार','Ashoka / अशोक','Samudragupta / समुद्रगुप्त','Akbar / अकबर'],2,'Ashoka used rock and pillar edicts to communicate policy and dhamma. / अशोक ने नीतियों और धम्म के प्रचार हेतु शिला और स्तंभ लेखों का प्रयोग किया।'),
('History',4,'Which historical author and work are correctly matched? / किस ऐतिहासिक लेखक और रचना का युग्म सही है?',array['Al-Biruni - Kitab-ul-Hind / अल-बिरूनी - किताब-उल-हिंद','Kalhana - Ain-i-Akbari / कल्हण - आईन-ए-अकबरी','Abul Fazl - Rajatarangini / अबुल फजल - राजतरंगिणी','Banabhatta - Arthashastra / बाणभट्ट - अर्थशास्त्र'],1,'Al-Biruni wrote Kitab-ul-Hind; Kalhana wrote Rajatarangini. / अल-बिरूनी ने किताब-उल-हिंद और कल्हण ने राजतरंगिणी लिखी।'),
('History',5,'Arrange chronologically: Plassey, Buxar, Permanent Settlement. / कालक्रम चुनें: प्लासी, बक्सर, स्थायी बंदोबस्त।',array['Buxar, Plassey, Settlement / बक्सर, प्लासी, बंदोबस्त','Plassey, Buxar, Settlement / प्लासी, बक्सर, बंदोबस्त','Settlement, Plassey, Buxar / बंदोबस्त, प्लासी, बक्सर','Plassey, Settlement, Buxar / प्लासी, बंदोबस्त, बक्सर'],2,'The dates are 1757, 1764 and 1793 respectively. / संबंधित वर्ष क्रमशः 1757, 1764 और 1793 हैं।'),
('History',6,'Which combination correctly describes the Ryotwari system? / रैयतवाड़ी व्यवस्था का सही वर्णन?',array['Settlement directly with cultivators / कृषकों से प्रत्यक्ष राजस्व समझौता','Permanent settlement with zamindars everywhere / हर जगह जमींदारों से स्थायी बंदोबस्त','No land revenue / कोई भू-राजस्व नहीं','Revenue collected only by village communities / केवल ग्राम समुदाय से राजस्व'],1,'Ryotwari assessed revenue directly on individual cultivators, unlike zamindari settlement. / रैयतवाड़ी में व्यक्तिगत कृषकों से सीधे भू-राजस्व तय किया जाता था।'),
('History',7,'Which event caused Gandhi to withdraw Non-Cooperation in 1922? / 1922 में गांधीजी ने किस घटना के बाद असहयोग आंदोलन वापस लिया?',array['Jallianwala Bagh / जलियाँवाला बाग','Chauri Chaura / चौरी चौरा','Dandi March / दांडी मार्च','Kakori incident / काकोरी घटना'],2,'Violence at Chauri Chaura prompted withdrawal in February 1922. / चौरी चौरा की हिंसा के बाद फरवरी 1922 में आंदोलन वापस लिया गया।'),
('History',8,'Which was proposed by the Cabinet Mission Plan of 1946? / 1946 की कैबिनेट मिशन योजना में क्या प्रस्तावित था?',array['Immediate partition into two sovereign states / तत्काल दो संप्रभु राज्यों में विभाजन','A Union handling defence, foreign affairs and communications / रक्षा, विदेश मामले और संचार संभालने वाला संघ','A directly elected President with all powers / सर्वशक्तिमान प्रत्यक्ष निर्वाचित राष्ट्रपति','Abolition of all provinces / सभी प्रांतों की समाप्ति'],2,'The plan proposed a limited Union with provincial groupings, not immediate partition. / योजना में प्रांतीय समूहों के साथ सीमित शक्तियों वाला संघ था, तत्काल विभाजन नहीं।'),
('History',9,'Which pair of statements about the 1935 Act is correct? / 1935 के अधिनियम के बारे में कौन-से कथन सही हैं?',array['Provincial autonomy introduced; proposed federation never fully established / प्रांतीय स्वायत्तता आई; प्रस्तावित संघ पूरी तरह स्थापित नहीं हुआ','Dyarchy ended at the Centre; universal franchise introduced / केंद्र में द्वैध शासन समाप्त; सार्वभौम मताधिकार आया','All princely states joined the federation / सभी रियासतें संघ में शामिल हुईं','India immediately became a republic / भारत तुरंत गणराज्य बना'],1,'Provincial autonomy operated from 1937, but the all-India federation did not materialise. / 1937 से प्रांतीय स्वायत्तता लागू हुई, किंतु अखिल भारतीय संघ स्थापित नहीं हुआ।'),
('History',10,'Which sequence of events in the 1940s is chronological? / 1940 के दशक की घटनाओं का सही कालक्रम कौन-सा है?',array['Cripps Mission, Quit India, Cabinet Mission, Mountbatten Plan / क्रिप्स मिशन, भारत छोड़ो, कैबिनेट मिशन, माउंटबेटन योजना','Quit India, Cripps Mission, Mountbatten Plan, Cabinet Mission / भारत छोड़ो, क्रिप्स मिशन, माउंटबेटन योजना, कैबिनेट मिशन','Cabinet Mission, Cripps Mission, Quit India, Mountbatten Plan / कैबिनेट मिशन, क्रिप्स मिशन, भारत छोड़ो, माउंटबेटन योजना','Cripps Mission, Cabinet Mission, Quit India, Mountbatten Plan / क्रिप्स मिशन, कैबिनेट मिशन, भारत छोड़ो, माउंटबेटन योजना'],1,'Cripps arrived in March 1942; Quit India began in August 1942; Cabinet Mission in 1946; Mountbatten Plan in June 1947. / क्रम: मार्च 1942, अगस्त 1942, 1946, जून 1947।'),
('Geography',1,'Which is the largest ocean by area? / क्षेत्रफल में सबसे बड़ा महासागर कौन-सा है?',array['Atlantic / अटलांटिक','Indian / हिंद','Arctic / आर्कटिक','Pacific / प्रशांत'],4,'The Pacific Ocean has the greatest area. / प्रशांत महासागर का क्षेत्रफल सबसे अधिक है।'),
('Geography',2,'The Tropic of Cancer lies at approximately which latitude? / कर्क रेखा लगभग किस अक्षांश पर है?',array['23.5 degrees N / 23.5 अंश उत्तर','23.5 degrees S / 23.5 अंश दक्षिण','66.5 degrees N / 66.5 अंश उत्तर','0 degrees / 0 अंश'],1,'The Tropic of Cancer is about 23.5 degrees north of the Equator. / कर्क रेखा भूमध्य रेखा से लगभग 23.5 अंश उत्तर में है।'),
('Geography',3,'Which river flows west into the Arabian Sea? / कौन-सी नदी पश्चिम की ओर अरब सागर में गिरती है?',array['Godavari / गोदावरी','Mahanadi / महानदी','Narmada / नर्मदा','Krishna / कृष्णा'],3,'The Narmada flows west through a rift valley. / नर्मदा भ्रंश घाटी से पश्चिम की ओर बहती है।'),
('Geography',4,'Which soil is particularly suitable for cotton and retains moisture well? / कौन-सी मिट्टी कपास के लिए उपयुक्त है और नमी रोकती है?',array['Black soil / काली मिट्टी','Desert sand / मरुस्थलीय रेत','Laterite only / केवल लेटराइट','Mountain scree / पर्वतीय मलबा'],1,'Black soil has high clay content and moisture retention. / काली मिट्टी में चिकनी मिट्टी अधिक होती है और नमी धारण क्षमता अच्छी होती है।'),
('Geography',5,'Why does the windward side of the Western Ghats get heavy rain? / पश्चिमी घाट की पवनमुखी ढाल पर अधिक वर्षा क्यों होती है?',array['Descending dry air / उतरती शुष्क हवा','Moist air rises, cools and condenses / नम हवा ऊपर उठकर ठंडी होती और संघनित होती है','No monsoon reaches it / मानसून पहुँचता ही नहीं','Ocean currents directly create snow / धाराएँ सीधे बर्फ बनाती हैं'],2,'Orographic uplift cools moist monsoon air and produces rain. / पर्वतीय अवरोध से नम मानसूनी हवा उठकर ठंडी होती है और वर्षा करती है।'),
('Geography',6,'When it is noon at Greenwich, what is Indian Standard Time? / ग्रीनविच में दोपहर 12 बजे हों तो भारतीय मानक समय क्या होगा?',array['06:30','12:00','17:30','18:00'],3,'IST is UTC+5:30, based on 82.5 degrees E. / 82.5 अंश पूर्व पर आधारित भारतीय समय ग्रीनविच से 5 घंटे 30 मिनट आगे है।'),
('Geography',7,'Which explains dry winters over much of northern India? / उत्तरी भारत के बड़े भाग में शुष्क शीत ऋतु का मुख्य कारण?',array['Onshore southwest monsoon all winter / पूरी सर्दी समुद्र से दक्षिण-पश्चिम मानसून','Predominantly continental offshore winds, with some western disturbances / मुख्यतः स्थलीय शुष्क पवनें, बीच-बीच में पश्चिमी विक्षोभ','Permanent polar night / स्थायी ध्रुवीय रात','No pressure differences / दाब का कोई अंतर नहीं'],2,'Winter winds are generally dry; western disturbances bring some rain to the northwest. / शीतकालीन पवनें सामान्यतः शुष्क हैं; पश्चिमी विक्षोभ उत्तर-पश्चिम में कुछ वर्षा लाते हैं।'),
('Geography',8,'During El Nino, which change occurs in the tropical Pacific? / एल नीनो में उष्णकटिबंधीय प्रशांत में क्या परिवर्तन होता है?',array['Unusual warming of central/eastern equatorial surface waters / मध्य और पूर्वी विषुवतीय सतही जल का असामान्य गर्म होना','Permanent freezing of the equator / विषुवत क्षेत्र का स्थायी जमना','Uniform cooling of all oceans / सभी महासागरों का समान ठंडा होना','No ocean-atmosphere interaction / महासागर-वायुमंडल में कोई संबंध नहीं'],1,'El Nino is associated with anomalous warming in the central/eastern equatorial Pacific and altered circulation. / एल नीनो में मध्य और पूर्वी विषुवतीय प्रशांत गर्म होता है तथा परिसंचरण बदलता है।'),
('Geography',9,'Two cities at 75 degrees E and 90 degrees E compare local solar noon. Which is correct? / 75 अंश पूर्व और 90 अंश पूर्व के नगरों में स्थानीय सौर दोपहर की तुलना करें।',array['90 E reaches noon 1 hour earlier / 90 पूर्व में दोपहर 1 घंटा पहले','75 E reaches noon 1 hour earlier / 75 पूर्व में दोपहर 1 घंटा पहले','Both always have identical solar time / दोनों का सौर समय समान','Difference is 15 hours / अंतर 15 घंटे'],1,'Earth rotates 15 degrees per hour; the eastern city reaches solar noon earlier. / पृथ्वी 1 घंटे में 15 अंश घूमती है; पूर्वी नगर में सौर दोपहर पहले आती है।'),
('Geography',10,'A plateau has permeable limestone, caves and disappearing streams. Which process best explains this landscape? / पठार पर पारगम्य चूना पत्थर, गुफाएँ और लुप्त होती धाराएँ हैं। कौन-सी प्रक्रिया कारण है?',array['Only glacial abrasion / केवल हिमानी घर्षण','Carbonation and solution by weakly acidic water / हल्के अम्लीय जल से कार्बोनेटीकरण और घुलना','Only wind deposition / केवल पवन निक्षेपण','Only lava accumulation / केवल लावा संचय'],2,'Carbon dioxide in water forms weak carbonic acid that dissolves limestone, producing karst. / जल में कार्बन डाइऑक्साइड से बना कमजोर कार्बोनिक अम्ल चूना पत्थर घोलकर कार्स्ट स्थलाकृति बनाता है।');
insert into practice_bank values
('Economy',1,'Which institution issues most Indian currency notes? / भारत में अधिकांश मुद्रा नोट कौन जारी करता है?',array['RBI / भारतीय रिजर्व बैंक','SEBI / भारतीय प्रतिभूति एवं विनिमय बोर्ड','NITI Aayog / नीति आयोग','Finance Commission / वित्त आयोग'],1,'RBI issues banknotes; the one-rupee note is issued by the Government of India. / बैंक नोट रिजर्व बैंक जारी करता है; एक रुपये का नोट भारत सरकार जारी करती है।'),
('Economy',2,'A sustained rise in the general price level is called what? / सामान्य मूल्य स्तर में निरंतर वृद्धि क्या कहलाती है?',array['Deflation / अपस्फीति','Inflation / मुद्रास्फीति','Depreciation only / केवल मूल्यह्रास','Disinvestment / विनिवेश'],2,'Inflation concerns a general rise in prices, not just one product. / मुद्रास्फीति सामान्य कीमतों में वृद्धि है, केवल एक वस्तु में नहीं।'),
('Economy',3,'GDP measures which of the following? / सकल घरेलू उत्पाद क्या मापता है?',array['Only exports / केवल निर्यात','Final goods and services produced within the domestic territory in a period / अवधि में घरेलू सीमा में उत्पादित अंतिम वस्तुएँ और सेवाएँ','All intermediate sales added again / सभी मध्यवर्ती बिक्री दोबारा जोड़ना','Only government revenue / केवल सरकारी राजस्व'],2,'GDP counts domestic production of final output, avoiding intermediate double counting. / जीडीपी अंतिम घरेलू उत्पादन मापता है, मध्यवर्ती वस्तुओं की दोहरी गणना नहीं करता।'),
('Economy',4,'Which is a direct tax? / कौन-सा प्रत्यक्ष कर है?',array['Personal income tax / व्यक्तिगत आयकर','GST / वस्तु एवं सेवा कर','Customs duty / सीमा शुल्क','Excise duty / उत्पाद शुल्क'],1,'Personal income tax is levied directly on the income of the taxpayer. / व्यक्तिगत आयकर सीधे करदाता की आय पर लगाया जाता है।'),
('Economy',5,'If nominal GDP rises 10% while the GDP deflator rises 10%, what happens to real GDP approximately (using the exact ratio)? / सांकेतिक जीडीपी और जीडीपी अपस्फीतिकारक दोनों 10% बढ़ें तो वास्तविक जीडीपी का क्या होगा?',array['Rises 20% / 20% बढ़ेगा','Rises 10% / 10% बढ़ेगा','Unchanged / अपरिवर्तित','Falls 10% / 10% घटेगा'],3,'Real GDP is nominal GDP divided by the price index; 1.10/1.10 = 1. / वास्तविक जीडीपी में मूल्य प्रभाव हटता है; 1.10/1.10 = 1, इसलिए परिवर्तन नहीं।'),
('Economy',6,'What is the likely first-order effect of an RBI repo-rate increase, other things equal? / अन्य बातें समान हों तो रेपो दर बढ़ने का संभावित प्रारंभिक प्रभाव?',array['Cheaper bank borrowing from RBI / रिजर्व बैंक से बैंकों की उधारी सस्ती','Costlier borrowing and weaker credit demand / महँगी उधारी और ऋण माँग में कमी','Automatic doubling of GDP / जीडीपी स्वतः दुगुनी','All taxes disappear / सभी कर समाप्त'],2,'Higher policy borrowing costs tend to raise lending costs and restrain demand. / नीति दर बढ़ने से ऋण लागत बढ़ सकती है और माँग नियंत्रित हो सकती है।'),
('Economy',7,'Which formula defines the primary deficit? / प्राथमिक घाटे का सूत्र कौन-सा है?',array['Fiscal deficit + interest payments / राजकोषीय घाटा + ब्याज भुगतान','Fiscal deficit - interest payments / राजकोषीय घाटा - ब्याज भुगतान','Revenue receipts - expenditure / राजस्व प्राप्तियाँ - व्यय','Exports - imports / निर्यात - आयात'],2,'The primary deficit excludes interest payments from the fiscal deficit. / प्राथमिक घाटे में राजकोषीय घाटे से ब्याज भुगतान घटाया जाता है।'),
('Economy',8,'Domestic currency depreciates, other things equal. Which effect is most plausible? / अन्य बातें समान हों और घरेलू मुद्रा का अवमूल्यन हो तो संभावित प्रभाव?',array['Imports become cheaper in domestic currency / घरेलू मुद्रा में आयात सस्ता','Imports become costlier in domestic currency / घरेलू मुद्रा में आयात महँगा','All foreign prices become zero / सभी विदेशी मूल्य शून्य','Trade volumes must remain fixed forever / व्यापार मात्रा सदा स्थिर'],2,'More domestic currency is needed per unit of foreign currency, raising import costs. / विदेशी मुद्रा की प्रति इकाई अधिक घरेलू मुद्रा चाहिए, इसलिए आयात लागत बढ़ती है।'),
('Economy',9,'A factory pollutes a river without paying the damage cost. Which concept applies most directly? / कारखाना क्षति का भुगतान किए बिना नदी प्रदूषित करता है। कौन-सी अवधारणा लागू है?',array['Positive externality / सकारात्मक बाह्यता','Negative externality / नकारात्मक बाह्यता','Perfect internalisation / पूर्ण आंतरिकीकरण','A pure public good / शुद्ध सार्वजनिक वस्तु'],2,'An uncompensated cost imposed on third parties is a negative externality. / तीसरे पक्ष पर डाली गई बिना क्षतिपूर्ति की लागत नकारात्मक बाह्यता है।'),
('Economy',10,'Government spending is 1200, non-borrowing receipts 900 and interest payments 100. What are fiscal and primary deficits? / सरकारी व्यय 1200, उधारी रहित प्राप्तियाँ 900 और ब्याज 100 हैं। राजकोषीय व प्राथमिक घाटे?',array['300 and 200 / 300 और 200','200 and 300 / 200 और 300','400 and 300 / 400 और 300','300 and 400 / 300 और 400'],1,'Fiscal deficit = 1200-900 = 300; primary deficit = 300-100 = 200. / राजकोषीय घाटा 300 और ब्याज घटाकर प्राथमिक घाटा 200 है।'),
('Environment',1,'Which organism is a producer in a food chain? / खाद्य शृंखला में उत्पादक कौन है?',array['Green plant / हरा पौधा','Tiger / बाघ','Deer / हिरण','Vulture / गिद्ध'],1,'Green plants make organic food by photosynthesis. / हरे पौधे प्रकाश संश्लेषण से जैविक भोजन बनाते हैं।'),
('Environment',2,'Which gas is a major human-driven contributor to global warming? / मानवजनित वैश्विक तापवृद्धि में प्रमुख गैस कौन-सी है?',array['Nitrogen / नाइट्रोजन','Oxygen / ऑक्सीजन','Carbon dioxide / कार्बन डाइऑक्साइड','Argon / आर्गन'],3,'Carbon dioxide from activities such as fossil-fuel combustion increases greenhouse forcing. / जीवाश्म ईंधन जलाने जैसी गतिविधियों से निकली कार्बन डाइऑक्साइड ग्रीनहाउस प्रभाव बढ़ाती है।'),
('Environment',3,'Which protects animals within their natural habitat? / प्राकृतिक आवास में जीवों का संरक्षण कौन-सा है?',array['In-situ conservation / स्व-स्थाने संरक्षण','A seed bank alone / केवल बीज बैंक','A zoo alone / केवल चिड़ियाघर','Cryopreservation alone / केवल निम्नताप संरक्षण'],1,'In-situ conservation protects species where they naturally occur. / स्व-स्थाने संरक्षण जीवों को उनके प्राकृतिक स्थान में सुरक्षित रखता है।'),
('Environment',4,'What does the Ramsar Convention primarily concern? / रामसर अभिसमय मुख्यतः किससे संबंधित है?',array['Outer space / बाह्य अंतरिक्ष','Wetlands / आर्द्रभूमियाँ','Nuclear testing / परमाणु परीक्षण','Deep mining / गहरा खनन'],2,'Ramsar promotes conservation and wise use of wetlands. / रामसर आर्द्रभूमियों के संरक्षण और विवेकपूर्ण उपयोग को बढ़ावा देता है।'),
('Environment',5,'Excess fertiliser enters a lake. Which sequence is most likely? / झील में अधिक उर्वरक पहुँचे तो संभावित क्रम?',array['Algal growth, decomposition, oxygen depletion / शैवाल वृद्धि, अपघटन, ऑक्सीजन की कमी','Immediate oxygen doubling forever / ऑक्सीजन तुरंत सदा दुगुनी','No biological change / कोई जैविक परिवर्तन नहीं','All nutrients disappear / सभी पोषक तत्व गायब'],1,'Nutrient enrichment can trigger blooms; decomposition consumes dissolved oxygen. / पोषक वृद्धि से शैवाल बढ़ते हैं और अपघटन में घुली ऑक्सीजन खर्च होती है।'),
('Environment',6,'A persistent pesticide reaches its highest concentration in top predators. What is this called? / स्थायी कीटनाशक की अधिकतम सांद्रता शीर्ष परभक्षियों में मिलती है। इसे क्या कहते हैं?',array['Biomagnification / जैव आवर्धन','Nitrogen fixation / नाइट्रोजन स्थिरीकरण','Primary succession / प्राथमिक अनुक्रमण','Transpiration / वाष्पोत्सर्जन'],1,'Biomagnification increases concentration at successive trophic levels. / जैव आवर्धन में ऊँचे पोषण स्तरों पर सांद्रता बढ़ती जाती है।'),
('Environment',7,'Which combination supports biodiversity-hotspot designation? / जैव विविधता हॉटस्पॉट की पहचान में कौन-सा संयोजन महत्वपूर्ण है?',array['Low endemism and intact habitat only / कम स्थानिकता और केवल अक्षुण्ण आवास','High plant endemism and severe habitat loss / उच्च पादप स्थानिकता और गंभीर आवास हानि','Only large human population / केवल बड़ी मानव आबादी','Only high annual rainfall / केवल अधिक वार्षिक वर्षा'],2,'Hotspot criteria combine exceptional endemic vascular plants with substantial original-habitat loss. / मानदंडों में अत्यधिक स्थानिक संवहनी पादप तथा मूल आवास की भारी हानि शामिल हैं।'),
('Environment',8,'Removing a keystone predator changes many species despite its low abundance. What explains this? / कम संख्या वाले प्रमुख परभक्षी को हटाने से कई प्रजातियाँ बदल जाती हैं। कारण?',array['Only its body mass matters / केवल शरीर का भार महत्वपूर्ण','Its ecological effect is disproportionately large / उसका पारिस्थितिक प्रभाव अनुपात से बहुत अधिक है','Predators never affect prey / परभक्षी शिकार को प्रभावित नहीं करते','Food webs have no links / खाद्य जाल में संबंध नहीं'],2,'Keystone species can regulate food webs out of proportion to their abundance. / कीस्टोन प्रजातियाँ कम संख्या में भी खाद्य जाल पर बड़ा प्रभाव डालती हैं।'),
('Environment',9,'Which pair correctly distinguishes mitigation from adaptation? / शमन और अनुकूलन का सही भेद कौन-सा है?',array['Solar energy cuts emissions; flood-resilient buildings reduce vulnerability / सौर ऊर्जा उत्सर्जन घटाती है; बाढ़रोधी भवन संवेदनशीलता घटाते हैं','Sea walls cut all CO2; coal burning is adaptation / समुद्री दीवारें सारा CO2 घटाती हैं; कोयला जलाना अनुकूलन है','Both mean only planting trees / दोनों का अर्थ केवल वृक्षारोपण','Neither concerns climate / दोनों का जलवायु से संबंध नहीं'],1,'Mitigation addresses causes; adaptation reduces harm from climate impacts. / शमन कारणों को कम करता है; अनुकूलन जलवायु प्रभावों की हानि घटाता है।'),
('Environment',10,'A lake has high BOD and falling dissolved oxygen after sewage inflow. Which interpretation is best? / सीवेज आने पर झील का BOD अधिक और घुली ऑक्सीजन कम है। सर्वोत्तम अर्थ?',array['Little biodegradable matter is present / जैवअपघटनीय पदार्थ बहुत कम','Microbial decomposition is consuming oxygen / सूक्ष्मजीवी अपघटन ऑक्सीजन खर्च कर रहा है','High BOD proves pristine water / अधिक BOD शुद्ध जल का प्रमाण','Fish gain more oxygen automatically / मछलियों को स्वतः अधिक ऑक्सीजन'],2,'High biochemical oxygen demand indicates oxygen used by microbes decomposing organic waste. / अधिक जैवरासायनिक ऑक्सीजन माँग जैविक अपशिष्ट के अपघटन में सूक्ष्मजीवों द्वारा ऑक्सीजन खपत दर्शाती है।'),
('Science',1,'Which organ pumps blood in humans? / मनुष्य में रक्त कौन-सा अंग पंप करता है?',array['Heart / हृदय','Liver / यकृत','Kidney / वृक्क','Lung / फेफड़ा'],1,'The heart pumps blood through the circulatory system. / हृदय परिसंचरण तंत्र में रक्त पंप करता है।'),
('Science',2,'What is the SI unit of force? / बल का एसआई मात्रक क्या है?',array['Joule / जूल','Watt / वाट','Newton / न्यूटन','Pascal / पास्कल'],3,'Force is measured in newtons; one newton is one kg metre per second squared. / बल का मात्रक न्यूटन है; यह किलोग्राम मीटर प्रति सेकंड वर्ग के बराबर है।'),
('Science',3,'A solution has pH 3. It is __. / किसी विलयन का pH 3 है। वह __ है।',array['Acidic / अम्लीय','Neutral / उदासीन','Basic / क्षारीय','Always pure water / हमेशा शुद्ध जल'],1,'A pH below 7 indicates acidity under ordinary aqueous conditions. / सामान्य जलीय परिस्थितियों में 7 से कम pH अम्लीयता दर्शाता है।'),
('Science',4,'Which nutrient deficiency and disorder are correctly matched? / किस पोषक तत्व की कमी और रोग का युग्म सही है?',array['Vitamin C deficiency - scurvy / विटामिन C की कमी - स्कर्वी','Vitamin D deficiency - night blindness / विटामिन D की कमी - रतौंधी','Iron deficiency - goitre / लौह की कमी - घेंघा','Iodine deficiency - rickets / आयोडीन की कमी - रिकेट्स'],1,'Scurvy is caused by vitamin C deficiency; night blindness is linked to vitamin A. / विटामिन C की कमी से स्कर्वी और विटामिन A की कमी से रतौंधी होती है।'),
('Science',5,'A 6-ohm resistor carries 2 amperes. What voltage is across it? / 6 ओम प्रतिरोध में 2 ऐम्पियर धारा है। विभवांतर कितना है?',array['3 V','8 V','12 V','24 V'],3,'By Ohm''s law V = IR = 2 x 6 = 12 V. / ओम के नियम से V = IR = 12 वोल्ट।'),
('Science',6,'Why does a metal spoon feel colder than wood at the same room temperature? / समान कमरे के तापमान पर धातु का चम्मच लकड़ी से ठंडा क्यों लगता है?',array['Metal is always at a lower temperature / धातु का ताप हमेशा कम','Metal conducts heat away from skin faster / धातु त्वचा की ऊष्मा तेजी से ले जाती है','Wood creates heat / लकड़ी ऊष्मा बनाती है','Metal has no atoms / धातु में परमाणु नहीं'],2,'Higher thermal conductivity causes faster heat transfer from the skin. / अधिक ऊष्मा चालकता से त्वचा की ऊष्मा तेजी से बाहर जाती है।'),
('Science',7,'A 2 kg body accelerates at 3 m/s squared on a smooth surface. What net force acts? / चिकनी सतह पर 2 किग्रा पिंड का त्वरण 3 मीटर/सेकंड वर्ग है। परिणामी बल?',array['1.5 N','5 N','6 N','9 N'],3,'Newton''s second law gives F = ma = 2 x 3 = 6 N. / न्यूटन के दूसरे नियम से F = ma = 6 न्यूटन।'),
('Science',8,'Two 6-ohm resistors are in parallel, then in series with 3 ohms. Find total resistance. / दो 6 ओम प्रतिरोध समानांतर हैं, फिर उनके साथ 3 ओम श्रेणीक्रम में है। कुल प्रतिरोध?',array['3 ohms / ओम','6 ohms / ओम','9 ohms / ओम','15 ohms / ओम'],2,'The parallel pair equals 3 ohms; adding series 3 gives 6 ohms. / समानांतर युग्म 3 ओम है; श्रेणीक्रम के 3 ओम जोड़ने पर 6 ओम।'),
('Science',9,'In a cross Aa x Aa with complete dominance, what fraction shows the recessive phenotype? / पूर्ण प्रभाविता में Aa x Aa संकरण से अप्रभावी लक्षण का अनुपात?',array['1/4','1/2','3/4','1'],1,'Genotypes are AA, Aa, Aa, aa; only aa shows the recessive trait. / जीनप्ररूप AA, Aa, Aa, aa हैं; केवल aa में अप्रभावी लक्षण दिखता है।'),
('Science',10,'A 12 V battery drives a 6-ohm resistor for 5 minutes. What electrical energy is dissipated? / 12 वोल्ट बैटरी से 6 ओम प्रतिरोध में 5 मिनट धारा बहती है। कितनी विद्युत ऊर्जा खर्च हुई?',array['120 J','1200 J','3600 J','7200 J'],4,'P = V squared / R = 24 W; t = 300 s; energy = 24 x 300 = 7200 J. / शक्ति 24 वाट और समय 300 सेकंड है; ऊर्जा 7200 जूल।');
insert into practice_bank values
('West Bengal',1,'What is the capital of West Bengal? / पश्चिम बंगाल की राजधानी क्या है?',array['Kolkata / कोलकाता','Siliguri / सिलीगुड़ी','Durgapur / दुर्गापुर','Malda / मालदा'],1,'Kolkata is the state capital. / कोलकाता पश्चिम बंगाल की राजधानी है।'),
('West Bengal',2,'Which river flows beside Kolkata? / कोलकाता के किनारे कौन-सी नदी बहती है?',array['Teesta / तीस्ता','Hooghly / हुगली','Damodar / दामोदर','Torsa / तोरसा'],2,'Kolkata lies on the eastern bank of the Hooghly. / कोलकाता हुगली नदी के पूर्वी तट पर स्थित है।'),
('West Bengal',3,'Darjeeling is especially associated with which plantation crop? / दार्जिलिंग विशेष रूप से किस बागानी फसल के लिए प्रसिद्ध है?',array['Tea / चाय','Coffee / कॉफी','Rubber / रबड़','Coconut / नारियल'],1,'The Darjeeling hills are internationally known for tea. / दार्जिलिंग की पहाड़ियाँ चाय के लिए विश्वप्रसिद्ध हैं।'),
('West Bengal',4,'Who founded the Brahmo Sabha in 1828? / 1828 में ब्रह्म सभा की स्थापना किसने की?',array['Ishwar Chandra Vidyasagar / ईश्वरचंद्र विद्यासागर','Raja Rammohan Roy / राजा राममोहन राय','Bankim Chandra Chattopadhyay / बंकिमचंद्र चट्टोपाध्याय','Swami Vivekananda / स्वामी विवेकानंद'],2,'Raja Rammohan Roy founded the Brahmo Sabha, precursor of the Brahmo Samaj. / राजा राममोहन राय ने ब्रह्म सभा की स्थापना की, जो ब्रह्म समाज का पूर्वरूप थी।'),
('West Bengal',5,'Which Bengali author and literary work are correctly matched? / किस बंगाली लेखक और साहित्यिक रचना का युग्म सही है?',array['Bankim Chandra - Anandamath / बंकिमचंद्र - आनंदमठ','Rabindranath - Durgeshnandini / रवींद्रनाथ - दुर्गेशनंदिनी','Vidyasagar - Gitanjali / विद्यासागर - गीतांजलि','Sarat Chandra - Rajatarangini / शरतचंद्र - राजतरंगिणी'],1,'Bankim wrote Anandamath; Rabindranath wrote Gitanjali. / बंकिमचंद्र ने आनंदमठ और रवींद्रनाथ ने गीतांजलि लिखी।'),
('West Bengal',6,'The Tebhaga movement demanded what share of produce for sharecroppers? / तेभागा आंदोलन में बटाईदारों के लिए उपज का कितना हिस्सा माँगा गया?',array['One fourth / एक चौथाई','One third / एक तिहाई','One half / आधा','Two thirds / दो तिहाई'],4,'Tebhaga sought two thirds of the produce for the sharecropper instead of one half. / तेभागा में बटाईदार को आधे के स्थान पर दो तिहाई उपज देने की माँग थी।'),
('West Bengal',7,'Which combination correctly explains Sundarbans vegetation? / सुंदरबन की वनस्पति का सही कारण कौन-सा संयोजन है?',array['Arid climate and sand dunes / शुष्क जलवायु और बालू टीले','Tidal saline conditions and mangrove adaptations / ज्वारीय लवणीय दशाएँ और मैंग्रोव अनुकूलन','Permanent snow and conifers / स्थायी हिम और शंकुधारी वृक्ष','Freshwater-only alpine lakes / केवल मीठे पानी की अल्पाइन झीलें'],2,'Tidal estuaries favour salt-tolerant mangroves, often with specialised roots. / ज्वारीय मुहानों में लवण-सहिष्णु मैंग्रोव और विशेष जड़ें अनुकूल होती हैं।'),
('West Bengal',8,'Arrange the partition announcement, formal Swadeshi launch and annulment chronologically. / विभाजन की घोषणा, स्वदेशी के औपचारिक आरंभ और विभाजन रद्द होने का कालक्रम चुनें।',array['Announcement, Swadeshi launch, annulment / घोषणा, स्वदेशी आरंभ, विभाजन रद्द','Annulment, announcement, Swadeshi launch / विभाजन रद्द, घोषणा, स्वदेशी आरंभ','Swadeshi launch, annulment, announcement / स्वदेशी आरंभ, विभाजन रद्द, घोषणा','Annulment, Swadeshi launch, announcement / विभाजन रद्द, स्वदेशी आरंभ, घोषणा'],1,'Partition was announced in July 1905, followed by the formal Swadeshi launch in August; partition was annulled in 1911. / जुलाई 1905 में विभाजन की घोषणा हुई, अगस्त में स्वदेशी आंदोलन का औपचारिक आरंभ हुआ; 1911 में विभाजन रद्द हुआ।'),
('West Bengal',9,'Why did the Hooghly industrial belt historically attract jute mills? / हुगली औद्योगिक पट्टी में जूट मिलें ऐतिहासिक रूप से क्यों केंद्रित हुईं?',array['Nearby raw jute, water transport, labour and Kolkata port / निकट कच्चा जूट, जल परिवहन, श्रम और कोलकाता बंदरगाह','Only desert climate / केवल मरुस्थलीय जलवायु','No access to transport / परिवहन का अभाव','Only iron ore at every mill / हर मिल पर केवल लौह अयस्क'],1,'The combination of deltaic jute supply, river transport, labour and port access favoured the belt. / डेल्टा से जूट, नदी परिवहन, श्रमिक और बंदरगाह की सुविधा ने उद्योग को बढ़ावा दिया।'),
('West Bengal',10,'Which pair correctly distinguishes northern Bengal foothills from the Sundarbans? / उत्तरी बंगाल की तलहटी और सुंदरबन का सही भेद कौन-सा है?',array['Dooars - Himalayan foothills; Sundarbans - tidal delta / डुआर्स - हिमालयी तलहटी; सुंदरबन - ज्वारीय डेल्टा','Dooars - coral reef; Sundarbans - alpine meadow / डुआर्स - प्रवाल भित्ति; सुंदरबन - अल्पाइन घासभूमि','Both are glacial deserts / दोनों हिमानी मरुस्थल','Both are Deccan lava plateaus / दोनों दक्कन के लावा पठार'],1,'Dooars lies along the Himalayan foothills, while Sundarbans occupies the lower tidal delta. / डुआर्स हिमालय की तलहटी में और सुंदरबन निचले ज्वारीय डेल्टा में है।'),
('Kerala',1,'What is the capital of Kerala? / केरल की राजधानी क्या है?',array['Kochi / कोच्चि','Kozhikode / कोझिकोड','Thiruvananthapuram / तिरुवनंतपुरम','Thrissur / त्रिशूर'],3,'Thiruvananthapuram is the capital of Kerala. / तिरुवनंतपुरम केरल की राजधानी है।'),
('Kerala',2,'Which sea lies to the west of Kerala? / केरल के पश्चिम में कौन-सा सागर है?',array['Arabian Sea / अरब सागर','Bay of Bengal / बंगाल की खाड़ी','Red Sea / लाल सागर','Caspian Sea / कैस्पियन सागर'],1,'Kerala borders the Arabian Sea on the west. / केरल की पश्चिमी सीमा अरब सागर से लगती है।'),
('Kerala',3,'Which language is the principal official language of Kerala? / केरल की प्रमुख राजभाषा कौन-सी है?',array['Tamil / तमिल','Malayalam / मलयालम','Kannada / कन्नड़','Telugu / तेलुगु'],2,'Malayalam is the principal official language of Kerala. / मलयालम केरल की प्रमुख राजभाषा है।'),
('Kerala',4,'Kerala state was formed on which date? / केरल राज्य किस तिथि को बना?',array['15 August 1947 / 15 अगस्त 1947','26 January 1950 / 26 जनवरी 1950','1 November 1956 / 1 नवंबर 1956','1 May 1960 / 1 मई 1960'],3,'Kerala was formed on 1 November 1956 during linguistic reorganisation. / भाषाई पुनर्गठन के दौरान 1 नवंबर 1956 को केरल बना।'),
('Kerala',5,'Which reformer is associated with the Aruvippuram consecration of 1888? / 1888 की अरुविप्पुरम प्रतिष्ठा से कौन-से सुधारक जुड़े हैं?',array['Sree Narayana Guru / श्री नारायण गुरु','Ayyankali / अय्यंकाली','Chattampi Swamikal / चट्टम्पि स्वामिकल','Vakkom Moulavi / वक्कोम मौलवी'],1,'Sree Narayana Guru performed the consecration, challenging caste restrictions. / श्री नारायण गुरु ने जातिगत प्रतिबंधों को चुनौती देते हुए प्रतिष्ठा की।'),
('Kerala',6,'Which social reformer and organisation are correctly matched? / किस समाज सुधारक और संगठन का युग्म सही है?',array['Ayyankali - Sadhu Jana Paripalana Sangham / अय्यंकाली - साधु जन परिपालन संघम','Sree Narayana Guru - Arya Samaj / श्री नारायण गुरु - आर्य समाज','Raja Rammohan Roy - SNDP / राजा राममोहन राय - एसएनडीपी','Dayanand Saraswati - Brahmo Sabha / दयानंद सरस्वती - ब्रह्म सभा'],1,'Ayyankali founded Sadhu Jana Paripalana Sangham to advance oppressed communities. / अय्यंकाली ने वंचित समुदायों के उत्थान हेतु साधु जन परिपालन संघम बनाया।'),
('Kerala',7,'The Vaikom Satyagraha primarily challenged which restriction? / वैकोम सत्याग्रह मुख्यतः किस प्रतिबंध के विरुद्ध था?',array['Access to roads around a temple based on caste / जाति के आधार पर मंदिर के आसपास की सड़कों पर प्रवेश रोक','A ban on ocean trade / समुद्री व्यापार पर रोक','A tax on tea exports alone / केवल चाय निर्यात पर कर','A language examination / भाषा परीक्षा'],1,'The 1924-25 movement sought access to public roads around the Vaikom temple for excluded castes. / 1924-25 के आंदोलन में वंचित जातियों के लिए वैकोम मंदिर के पास सार्वजनिक सड़कों पर चलने का अधिकार माँगा गया।'),
('Kerala',8,'Why does Kerala receive heavy southwest monsoon rain? / केरल में दक्षिण-पश्चिम मानसून से भारी वर्षा क्यों होती है?',array['Moist Arabian Sea winds rise over the Western Ghats / अरब सागर की नम पवनें पश्चिमी घाट पर चढ़ती हैं','It lies in a polar zone / यह ध्रुवीय क्षेत्र में है','Only winter snowfall melts / केवल शीतकालीन हिम पिघलता है','The Ghats stop all clouds offshore / घाट सभी बादल समुद्र में रोक देते हैं'],1,'The windward coast and Ghats promote orographic rainfall from moist monsoon winds. / पवनमुखी तट और पश्चिमी घाट नम मानसूनी पवनों से पर्वतीय वर्षा कराते हैं।'),
('Kerala',9,'Which sequence is chronological in Kerala social history? / केरल के सामाजिक इतिहास का सही कालक्रम?',array['Aruvippuram consecration, Vaikom Satyagraha, Temple Entry Proclamation / अरुविप्पुरम प्रतिष्ठा, वैकोम सत्याग्रह, मंदिर प्रवेश घोषणा','Temple Entry Proclamation, Vaikom, Aruvippuram / मंदिर प्रवेश घोषणा, वैकोम, अरुविप्पुरम','Vaikom, Temple Entry Proclamation, Aruvippuram / वैकोम, मंदिर प्रवेश घोषणा, अरुविप्पुरम','Vaikom, Aruvippuram, Temple Entry Proclamation / वैकोम, अरुविप्पुरम, मंदिर प्रवेश घोषणा'],1,'The dates are 1888, 1924-25 and 1936 respectively. / संबंधित वर्ष क्रमशः 1888, 1924-25 और 1936 हैं।'),
('Kerala',10,'A coastal Kerala wetland has mixing of river water and tidal seawater. Which description best fits? / केरल की तटीय आर्द्रभूमि में नदी का जल और ज्वारीय समुद्री जल मिलते हैं। उपयुक्त वर्णन?',array['Brackish estuarine/backwater ecosystem / खारे-मीठे जल का मुहाना या बैकवाटर तंत्र','Freshwater glacier / मीठे पानी का हिमनद','Dry inland salt desert only / केवल शुष्क अंतर्देशीय लवण मरुस्थल','Deep-ocean trench / गहरी महासागरीय खाई'],1,'Freshwater and seawater mixing creates variable-salinity brackish habitats. / मीठे और समुद्री जल के मिश्रण से बदलती लवणता वाला खारा-मीठा आवास बनता है।'),
('Data Interpretation',1,'A branch opens 12 accounts on Monday and 18 on Tuesday. Find the total. / शाखा ने सोमवार को 12 और मंगलवार को 18 खाते खोले। कुल?',array['24','28','30','36'],3,'12 + 18 = 30 accounts. / 12 और 18 का योग 30 खाते है।'),
('Data Interpretation',2,'Requests processed: A=40, B=60, C=80. Find the average. / निपटाए अनुरोध: A=40, B=60, C=80। औसत?',array['50','60','70','80'],2,'Average = (40+60+80)/3 = 60. / कुल 180 को 3 से भाग देने पर औसत 60 है।'),
('Data Interpretation',3,'A branch processes 200 requests; 30% are online. How many are offline? / 200 अनुरोधों में 30% ऑनलाइन हैं। ऑफलाइन कितने?',array['60','100','140','170'],3,'Offline share = 70%; 200 x 0.7 = 140. / ऑफलाइन हिस्सा 70% है; 200 का 70% = 140।'),
('Data Interpretation',4,'Sales increase from 160 to 200. What is the percentage increase? / बिक्री 160 से 200 हुई। प्रतिशत वृद्धि?',array['20%','25%','30%','40%'],2,'Increase = 40/160 x 100 = 25%. / आधार 160 है; 40 की वृद्धि 25% है।'),
('Data Interpretation',5,'A processes 120 requests with 25% rejected; B processes 180 with 20% rejected. Total accepted? / A ने 120 में 25% और B ने 180 में 20% अनुरोध अस्वीकार किए। कुल स्वीकृत?',array['210','224','234','240'],3,'A accepts 90, B accepts 144; total 234. / A में 90 और B में 144 स्वीकृत; कुल 234।'),
('Data Interpretation',6,'A deposit of 4000 earns 5%; another of 6000 earns 10% for one year, simple interest. Combined effective rate? / 4000 पर 5% और 6000 पर 10% एक वर्ष का साधारण ब्याज है। संयुक्त प्रभावी दर?',array['7%','7.5%','8%','8.5%'],3,'Interest = 200+600 = 800 on 10000, so 8%. / कुल 10000 पर ब्याज 800 है, अर्थात 8%।'),
('Data Interpretation',7,'A branch has 20 staff averaging 30 years; 5 new staff average 25. Find the new average age. / 20 कर्मचारियों की औसत आयु 30 और 5 नए कर्मचारियों की 25 है। नया औसत?',array['28','29','30','31'],2,'Total age = 600+125 = 725; 725/25 = 29. / कुल आयु 725 और कर्मचारी 25 हैं; औसत 29 वर्ष।'),
('Data Interpretation',8,'Quarterly sales are 100, 120, 150, 180. What percentage of annual sales occur in the second half? / तिमाही बिक्री 100, 120, 150, 180 है। वर्ष की दूसरी छमाही का प्रतिशत?',array['50%','55%','60%','65%'],3,'Second half = 330; annual total = 550; 330/550 = 60%. / दूसरी छमाही 330 और कुल 550 है; अनुपात 60%।'),
('Data Interpretation',9,'Branch A handles 300 applications at 80% acceptance, B handles 200 at 60%. Find overall acceptance. / A में 300 आवेदनों की स्वीकृति 80%, B में 200 की 60% है। कुल स्वीकृति प्रतिशत?',array['68%','70%','72%','75%'],3,'Accepted = 240+120 = 360 out of 500; 72%. / 500 में 360 आवेदन स्वीकृत हैं; प्रतिशत 72%।'),
('Data Interpretation',10,'Applications rise 25%, while rejection falls from 20% to 12%. By what percentage do accepted applications rise? / आवेदन 25% बढ़े और अस्वीकृति दर 20% से 12% हुई। स्वीकृत आवेदनों में प्रतिशत वृद्धि?',array['25%','30%','37.5%','40%'],3,'Take initial total 100: accepted 80. New total 125: accepted 110. Growth = 30/80 = 37.5%. / पहले 100 में 80 स्वीकृत; अब 125 में 110। वृद्धि 30/80 = 37.5%।'),
('Logic',1,'Which is different: 2, 4, 6, 9? / भिन्न संख्या चुनें: 2, 4, 6, 9।',array['2','4','6','9'],4,'Only 9 is odd; the others are even. / केवल 9 विषम है, शेष सम हैं।'),
('Logic',2,'A is taller than B; B taller than C. Who is tallest? / A, B से लंबा है और B, C से लंबा है। सबसे लंबा कौन?',array['A','B','C','Cannot determine / निर्धारित नहीं'],1,'The ordering is A > B > C. / क्रम A > B > C है; A सबसे लंबा है।'),
('Logic',3,'If BANK becomes CBOL by shifting each letter one place, how is CASH coded? / हर अक्षर एक स्थान आगे करने पर BANK का CBOL है। CASH का कूट?',array['DBTI','DBSH','CBTI','ECUJ'],1,'C to D, A to B, S to T, H to I gives DBTI. / प्रत्येक अक्षर आगे करने पर DBTI मिलता है।'),
('Logic',4,'Find the next term: 3, 8, 15, 24, 35, __. / अगला पद ज्ञात करें: 3, 8, 15, 24, 35, __।',array['46','47','48','49'],3,'Differences are 5,7,9,11, then 13; 35+13=48. / अंतर क्रमशः 5,7,9,11 हैं; अगला अंतर 13 है, इसलिए 48।'),
('Logic',5,'All tokens are cards. No card is cash. Which must be true? / सभी टोकन कार्ड हैं। कोई कार्ड नकद नहीं है। क्या अवश्य सही है?',array['Some tokens are cash / कुछ टोकन नकद हैं','No token is cash / कोई टोकन नकद नहीं है','All cash is token / सभी नकद टोकन हैं','No cash exists / नकद का अस्तित्व नहीं'],2,'Tokens belong to the card set, which excludes cash. / टोकन कार्ड के समूह में हैं और उस समूह में नकद नहीं है।'),
('Logic',6,'A is B''s mother; C is A''s brother; D is C''s daughter. How is D related to B? / A, B की माता है; C, A का भाई है; D, C की बेटी है। D का B से संबंध?',array['Sister / बहन','Mother / माता','Cousin / ममेरी बहन','Aunt / मौसी'],3,'D is the daughter of B''s maternal uncle, hence a cousin. / D, B के मामा की बेटी है, इसलिए ममेरी बहन है।'),
('Logic',7,'P > Q >= R = S < T. Which must hold? / P > Q >= R = S < T में क्या अवश्य सही है?',array['P > S','P > T','T > Q','Q = S'],1,'P > Q and Q >= S imply P > S. T has no fixed relation to P or Q. / P > Q तथा Q >= S से P > S; T का P या Q से निश्चित संबंध नहीं।'),
('Logic',8,'Compare roots: x squared - 9x + 20 = 0; y squared - 5y + 6 = 0. / मूलों की तुलना करें: x² - 9x + 20 = 0; y² - 5y + 6 = 0।',array['x > y always / हमेशा x > y','x < y always / हमेशा x < y','x = y always / हमेशा x = y','No fixed relation / निश्चित संबंध नहीं'],1,'x is 4 or 5; y is 2 or 3. Every x is greater than every y. / x के मूल 4,5 और y के 2,3 हैं; हर स्थिति में x > y।'),
('Logic',9,'A, B, C, D, E face north. C is in the middle; A is immediately left of B; E is at the right end. Who is second from right? / A, B, C, D, E उत्तरमुखी हैं। C बीच में, A ठीक B के बाएँ और E दाएँ छोर पर है। दाएँ से दूसरा?',array['A','B','C','D'],4,'The only arrangement is A B C D E; D is second from right. / एकमात्र क्रम A B C D E है; दाएँ से दूसरा D है।'),
('Logic',10,'Compare roots: x squared - 13x + 42 = 0; y squared - 15y + 56 = 0. / मूलों की तुलना करें: x² - 13x + 42 = 0; y² - 15y + 56 = 0।',array['x > y always / हमेशा x > y','x < y always / हमेशा x < y','x <= y always / हमेशा x <= y','x = y always / हमेशा x = y'],3,'x is 6 or 7; y is 7 or 8. Thus x <= y, with equality possible at 7. / x के मूल 6,7 तथा y के 7,8 हैं। इसलिए x <= y और 7 पर बराबरी संभव है।');
