begin;


create temporary table new_series (
  number integer primary key, category integer not null,
  title text not null, subjects text not null, topics text[] not null
) on commit drop;


  id, series_id, level, category_id, title, description,
  duration_minutes, total_marks, negative_marking_rate, is_published
)
select
  (case when level = 1 then '20000000-0000-0000-0000-'
    else '21000000-0000-0000-' || lpad(level::text, 4, '0') || '-' end || lpad(s.number::text, 12, '0'))::uuid,
  ('20000000-0000-0000-0000-' || lpad(s.number::text, 12, '0'))::uuid,
  level,
  ('10000000-0000-0000-0000-' || lpad(s.category::text, 12, '0'))::uuid,
  s.title,
  'English + Hindi. Five-question practice sets, not full-length official mocks. ' || s.subjects,
  10, 5, 0.25, true
from new_series s cross join generate_series(1, 10) level;

-- Reusable syllabus-aligned items are shared across related exams. Within each
-- series, every level uses new items and progresses from recall to application.
create temporary table practice_bank (
  topic text not null, level integer not null check (level between 1 and 10),
  question text not null, choices text[] not null check (cardinality(choices) = 4),
  answer integer not null check (answer between 1 and 4), explanation text not null,
  primary key (topic, level)
) on commit drop;





  id, exam_id, position, question_text, options, correct_option_id, explanation, topic
)
select
  ('31000000-0000-' || lpad(s.number::text, 4, '0') || '-' ||
    lpad(b.level::text, 4, '0') || '-' || lpad(t.position::text, 12, '0'))::uuid,
  (case when b.level = 1 then '20000000-0000-0000-0000-'
    else '21000000-0000-0000-' || lpad(b.level::text, 4, '0') || '-' end || lpad(s.number::text, 12, '0'))::uuid,
  t.position::integer,
  b.question,
  (select jsonb_agg(jsonb_build_object('id', chr(64 + choice.position::integer), 'text', choice.text) order by choice.position)
   from unnest(b.choices) with ordinality choice(text, position)),
  chr(64 + b.answer),
  b.explanation,
  b.topic
from new_series s
cross join lateral unnest(s.topics) with ordinality t(topic, position)
join practice_bank b on b.topic = t.topic;

do $$
begin
  if (select count(*) from public.exams where series_id in (
    select ('20000000-0000-0000-0000-' || lpad(number::text, 12, '0'))::uuid from new_series
  )) <> 100 or exists (
    select 1 from public.exams e
    where e.series_id in (
      select ('20000000-0000-0000-0000-' || lpad(number::text, 12, '0'))::uuid from new_series
    ) and (select count(*) from public.questions q where q.exam_id = e.id) <> 5
  ) then
    raise exception 'Expected ten series with ten five-question levels each.';
  end if;
end;
$$;

notify pgrst, 'reload schema';
commit;
